'use strict';
const $=id=>document.getElementById(id);
const formats={Instagram:[['Portrait · 4:5',1080,1350],['Square · 1:1',1080,1080],['Story · 9:16',1080,1920]],TikTok:[['Vertical image · 9:16',1080,1920]],YouTube:[['Thumbnail · 16:9',1280,720],['Shorts cover · 9:16',1080,1920]]};
let source=null,output=null,active=false,cancelled=false,db;
const request=r=>new Promise((res,rej)=>{r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});
async function openDB(){const r=indexedDB.open('socialforge',1);r.onupgradeneeded=()=>r.result.createObjectStore('creations',{keyPath:'id'});db=await request(r);await history()}
function transaction(mode){return db.transaction('creations',mode)}
async function save(record){if(!db)return;const tx=transaction('readwrite');tx.objectStore('creations').put(record);await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});const rows=await request(transaction('readonly').objectStore('creations').getAll());if(rows.length>6){const t=transaction('readwrite');rows.sort((a,b)=>b.id-a.id).slice(6).forEach(x=>t.objectStore('creations').delete(x.id))}await history()}
async function history(){if(!db)return;const rows=await request(transaction('readonly').objectStore('creations').getAll());$('history').replaceChildren();for(const r of rows.sort((a,b)=>b.id-a.id)){const b=document.createElement('button'),im=document.createElement('img'),s=document.createElement('span');im.src=r.data;s.textContent=r.name+' · '+r.width+'×'+r.height;b.append(im,s);b.onclick=()=>show(r);$('history').append(b)}}
function resetFormat(){$('format').replaceChildren();formats[$('platform').value].forEach((f,i)=>{const o=document.createElement('option');o.value=i;o.textContent=f[0];$('format').append(o)})}resetFormat();$('platform').onchange=resetFormat;
function loadImage(url){return new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=()=>rej(new Error('This image could not be decoded. Please choose a valid JPG, PNG or WebP.'));im.src=url})}
$('file').onchange=async()=>{try{$('error').textContent='';source=null;const f=$('file').files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type))throw Error('Please select JPG, PNG or WebP.');if(f.size>8*1024*1024)throw Error('Image must be 8 MB or smaller.');const u=URL.createObjectURL(f);try{const im=await loadImage(u);if(im.width*im.height>25000000)throw Error('Image exceeds 25 megapixels. Please resize it.');source=im;$('status').textContent='Photo ready · '+im.width+' × '+im.height;}finally{URL.revokeObjectURL(u)}}catch(e){$('error').textContent=e.message}};
$('sample').onclick=async()=>{const c=document.createElement('canvas');c.width=c.height=900;const x=c.getContext('2d');x.fillStyle='#edece6';x.fillRect(0,0,900,900);x.fillStyle='#0002';x.beginPath();x.ellipse(460,760,200,35,0,0,7);x.fill();x.fillStyle='#879b72';x.beginPath();x.roundRect(300,200,300,530,70);x.fill();x.fillStyle='#293e30';x.fillRect(345,145,210,90);x.fillStyle='#f5f1dc';x.fillRect(320,360,260,220);x.fillStyle='#34492e';x.textAlign='center';x.font='bold 48px sans-serif';x.fillText('EVERYDAY',450,440);x.font='24px sans-serif';x.fillText('BOTANICAL CARE',450,500);source=await loadImage(c.toDataURL());$('name').value='Everyday botanical care';$('status').textContent='Sample product ready.';$('error').textContent=''};
function wrap(ctx,text,x,y,max,line){let row='',yy=y;for(const word of text.split(/\s+/)){const test=row?row+' '+word:word;if(ctx.measureText(test).width>max&&row){ctx.fillText(row,x,yy);row=word;yy+=line}else row=test}ctx.fillText(row,x,yy);return yy}
function render(im,w,h,values){const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d'),pal={lime:['#e8f3d3','#263d2c','#c6ed80'],violet:['#eee8fa','#36254e','#c9b0ef'],sand:['#f4e9d9','#523f30','#e5c29c']}[values.theme];x.fillStyle=pal[0];x.fillRect(0,0,w,h);const landscape=w>h,p=w*.065;x.fillStyle=pal[2];x.beginPath();x.arc(w*.85,h*.25,w*.42,0,7);x.fill();const box=landscape?[w*.52,h*.12,w*.42,h*.76]:[p,h*.30,w-2*p,h*.49];const scale=Math.min(box[2]/im.width,box[3]/im.height);x.drawImage(im,box[0]+(box[2]-im.width*scale)/2,box[1]+(box[3]-im.height*scale)/2,im.width*scale,im.height*scale);x.fillStyle=pal[1];x.font=`600 ${w*.022}px sans-serif`;x.fillText(values.name.toUpperCase(),p,h*.085,w*.86);x.font=`bold ${w*(landscape?.048:.067)}px sans-serif`;wrap(x,values.headline,p,h*(landscape?.30:.17),w*(landscape?.40:.86),w*.078);const by=h*(landscape?.75:.87);x.fillStyle=pal[1];x.beginPath();x.roundRect(p,by,w*.37,h*.055,12);x.fill();x.fillStyle=pal[0];x.font=`600 ${w*.021}px sans-serif`;x.fillText(values.cta,p+w*.025,by+h*.036,w*.32);return c.toDataURL('image/png')}
async function show(r){output=r;const im=await loadImage(r.data),c=$('canvas');c.width=r.width;c.height=r.height;c.getContext('2d').drawImage(im,0,0);c.hidden=false;$('empty').hidden=true;$('dimensions').textContent=r.width+' × '+r.height+' PX';$('result').textContent=r.name+' · PNG';$('download').disabled=false}
const pause=ms=>new Promise(r=>setTimeout(r,ms));
$('studio').onsubmit=async e=>{e.preventDefault();if(active)return;$('error').textContent='';if(!source){$('error').textContent='Upload a photo or try the sample product first.';return}const v={name:$('name').value.trim(),headline:$('headline').value.trim(),cta:$('cta').value.trim(),theme:$('theme').value};if(!v.name||!v.headline||!v.cta){$('error').textContent='Complete the product name, headline and call to action.';return}const [,w,h]=formats[$('platform').value][+$('format').value],im=source;active=true;cancelled=false;$('generate').disabled=true;$('cancel').hidden=false;try{for(const msg of ['Preparing image…','Composing template · simulated AI stage…','Rendering platform-sized PNG…']){$('status').textContent=msg;await pause(450);if(cancelled)throw Error('Generation cancelled. Your previous result is preserved.')}const r={id:Date.now(),name:v.name,width:w,height:h,data:render(im,w,h,v)};await show(r);try{await save(r);$('status').textContent='Creative ready. Saved on this device.'}catch{$('status').textContent='Creative ready. Local history could not be saved; download still works.'}}catch(e){$('error').textContent=e.message;$('status').textContent='Ready to try again.'}finally{active=false;$('generate').disabled=false;$('cancel').hidden=true}};
$('cancel').onclick=()=>{cancelled=true};$('download').onclick=()=>{if(!output)return;const a=document.createElement('a');a.href=output.data;a.download='socialforge-'+output.width+'x'+output.height+'.png';a.click()};$('clear').onclick=async()=>{if(!db)return;const tx=transaction('readwrite');tx.objectStore('creations').clear();tx.oncomplete=()=>history()};openDB().catch(()=>{$('status').textContent='Local storage unavailable. You can still generate and download.'});
